
//1)Escreva um programa que exiba na tela a seguinte sequência de números:
//0, 3, 6, 9, 12, 15, ... até 30
public class exercicio01 {

	public static void main(String[] args) {
		// TODO Auto-generated method stub

		int numero = 0;
		
		while(numero <=30) {
			System.out.println(numero);
			numero += 3;
		}
		
	}

}
